        let mut res = Vec::new();
        for f in fields {
            match f {
                StructField::List {
                    name,
                    typ,
                    len_expr,
                } => {
                    let lenfield = expr_lenfield(len_expr);
                    if let Some(lenfield) = lenfield {
                        let name = name.clone();
                        let typ = typ.clone();
                        let lenfield = lenfield.to_string();
                        // let lenfield_typ = fields
                        //     .iter()
                        //     .find_map(|f| match f {
                        //         StructField::Field { name, typ, .. } => {
                        //             if name == &lenfield {
                        //                 Some(typ.clone())
                        //             } else {
                        //                 None
                        //             }
                        //         }
                        //         _ => None,
                        //     })
                        //     .expect("can't find lenfield type");
                        res.push(ListField {
                            name,
                            typ,
                            lenfield,
                            // lenfield_typ,
                        });
                    }
                }
                StructField::ListNoLen { name, typ } => {
                    let name = name.clone();
                    let typ = typ.clone();
                    let lenfield = name.clone() + "_len";
                    res.push(ListField {
