use crate::delaunay::triangle::DTriangle;
use crate::delaunay::vertex::DVertex;
use crate::index::{Index, NIL_INDEX};
use crate::triangulation::int::Triangulation;
use i_overlay::i_float::int::point::IntPoint;
use i_overlay::i_float::triangle::Triangle;
use i_overlay::i_float::u128::UInt128;

pub struct Delaunay {
    pub triangles: Vec<DTriangle>,
}

impl Delaunay {
    pub fn to_triangulation(&self, shifted: usize) -> Triangulation {
        let mut indices = vec![NIL_INDEX; 3 * self.triangles.len()];
        let i_pnt = indices.as_mut_ptr();

        let mut max_index = 0;
        let mut j = 0;
        for triangle in self.triangles.iter() {
            let a = triangle.vertices[0];
            let b = triangle.vertices[1];
            let c = triangle.vertices[2];

            max_index = max_index.max(c.index).max(a.index.max(b.index));

            unsafe {
                *i_pnt.add(j) = a.index + shifted;
                *i_pnt.add(j + 1) = b.index + shifted;
                *i_pnt.add(j + 2) = c.index + shifted;
            }
            j += 3;
        }

        let mut points = vec![IntPoint::ZERO; max_index + 1];
        let p_pnt = points.as_mut_ptr();

        for triangle in self.triangles.iter() {
            let a = triangle.vertices[0];
            let b = triangle.vertices[1];
            let c = triangle.vertices[2];

            unsafe {
                *p_pnt.add(a.index) = a.point;
                *p_pnt.add(b.index) = b.point;
                *p_pnt.add(c.index) = c.point;
            }
        }

        Triangulation { points, indices }
    }

    pub(super) fn new(triangles: Vec<DTriangle>) -> Self {
        Self { triangles }
    }

    pub(crate) fn build(&mut self) {
        let count = self.triangles.len();
        let mut visit_marks = vec![false; count];

        let mut visit_index = 0;

        let mut origin = Vec::with_capacity(64);
        origin.push(0);

        let mut buffer = Vec::with_capacity(64);

        while !origin.is_empty() {
            let mut j = 0;
            while j < origin.len() {
                let i = origin[j];
                j += 1;

                let mut triangle = *unsafe { self.triangles.get_unchecked(i) };
                unsafe {
                    *visit_marks.get_unchecked_mut(i) = true;
                }
                for k in 0..3 {
                    let neighbor_index = triangle.neighbor_by_order(k);
                    if neighbor_index.is_nil() {
                        continue;
                    }
                    let neighbor = *unsafe { self.triangles.get_unchecked(neighbor_index) };
                    if self.swap(triangle, neighbor) {
                        triangle = *unsafe { self.triangles.get_unchecked(triangle.index) };
                        let neighbor = unsafe { self.triangles.get_unchecked(neighbor_index) };

                        let tna = triangle.na();
                        if tna.is_not_nil() && tna != neighbor.index {
                            buffer.push(tna);
                        }

                        let tnb = triangle.nb();
                        if tnb.is_not_nil() && tnb != neighbor.index {
                            buffer.push(tnb);
                        }

                        let tnc = triangle.nc();
                        if tnc.is_not_nil() && tnc != neighbor.index {
                            buffer.push(tnc);
                        }

                        let nna = neighbor.na();
                        if nna.is_not_nil() && nna != triangle.index {
                            buffer.push(nna);
                        }

                        let nnb = neighbor.nb();
                        if nnb.is_not_nil() && nnb != triangle.index {
                            buffer.push(nnb);
                        }

                        let nnc = neighbor.nc();
                        if nnc.is_not_nil() && nnc != triangle.index {
                            buffer.push(nnc);
                        }
                    }
                }
            }

            if buffer.is_empty() && visit_index < count {
                visit_index += 1;
                while visit_index < count {
                    let is_visited = unsafe { *visit_marks.get_unchecked(visit_index) };
                    if !is_visited {
                        buffer.push(visit_index);
                        break;
                    }
                    visit_index += 1;
                }
            }

            origin.clear();

            std::mem::swap(&mut origin, &mut buffer);
        }
    }

    fn swap(&mut self, abc: DTriangle, pbc: DTriangle) -> bool {
        let pi = pbc.opposite(abc.index);

        let p = pbc.vertex_by_order(pi);

        let bi: usize;
        let ci: usize;
        let a: DVertex; // opposite a-p
        let b: DVertex; // edge bc
        let c: DVertex;

        let ai = abc.opposite(pbc.index);
        match ai {
            0 => {
                bi = 1;
                ci = 2;
                a = abc.va();
                b = abc.vb();
                c = abc.vc();
            }
            1 => {
                bi = 2;
                ci = 0;
                a = abc.vb();
                b = abc.vc();
                c = abc.va();
            }
            _ => {
                bi = 0;
                ci = 1;
                a = abc.vc();
                b = abc.va();
                c = abc.vb();
            }
        }

        let is_pass = Self::condition(p.point, c.point, a.point, b.point);

        if is_pass {
            false
        } else {
            let is_abp_cw = Triangle::is_clockwise_point(a.point, b.point, p.point);

            let bp = pbc.neighbor(c.index);
            let cp = pbc.neighbor(b.index);
            let ab = abc.neighbor_by_order(ci);
            let ac = abc.neighbor_by_order(bi);

            // abc -> abp
            let abp: DTriangle;

            // pbc -> acp
            let acp: DTriangle;

            if is_abp_cw {
                abp = DTriangle::abc_bc_ac_ab(
                    abc.index, a, b, p, bp,        // a - bp
                    pbc.index, // p - ap
                    ab,        // b - ab
                );

                acp = DTriangle::abc_bc_ac_ab(
                    pbc.index, a, p, c, cp,        // a - cp
                    ac,        // p - ac
                    abc.index, // b - ap
                );
            } else {
                abp = DTriangle::abc_bc_ac_ab(
                    abc.index, a, p, b, bp,        // a - bp
                    ab,        // p - ab
                    pbc.index, // b - ap
                );

                acp = DTriangle::abc_bc_ac_ab(
                    pbc.index, a, c, p, cp,        // a - cp
                    abc.index, // p - ap
                    ac,        // b - ac
                )
            }

            // fix neighbor's link
            // ab, cp didn't change neighbor
            // bc -> ap, so no changes

            // ac (abc) is now edge of acp
            let ac_index = abc.neighbor_by_order(bi); // b - angle
            self.update_neighbor_index(ac_index, abc.index, acp.index);

            // bp (pbc) is now edge of abp
            let bp_index = pbc.neighbor(c.index); // c - angle
            self.update_neighbor_index(bp_index, pbc.index, abp.index);

            unsafe {
                *self.triangles.get_unchecked_mut(abc.index) = abp;
                *self.triangles.get_unchecked_mut(pbc.index) = acp;
            }
            true
        }
    }

    fn update_neighbor_index(&mut self, index: usize, old_neighbor: usize, new_neighbor: usize) {
        if index.is_not_nil() {
            let neighbor = unsafe { self.triangles.get_unchecked_mut(index) };
            neighbor.update_opposite(old_neighbor, new_neighbor);
        }
    }

    // if p0 is inside circumscribe circle of p1, p2, p3 return false
    // if p0 is inside circumscribe A + B > 180
    // return true if triangle satisfied condition and do not need flip triangles
    fn condition(p0: IntPoint, p1: IntPoint, p2: IntPoint, p3: IntPoint) -> bool {
        // x, y of all coordinates must be in range of i32
        // p1, p2, p3 points of current triangle
        // p0 is a test point
        // p1 and p3 common points of triangle p1, p2, p3 and p1, p0, p2
        // alpha (A) is an angle of p1, p0, p3
        // beta (B) is an angle of p1, p2, p3

        let v10 = p1.subtract(p0);
        let v30 = p3.subtract(p0);

        let v12 = p1.subtract(p2);
        let v32 = p3.subtract(p2);

        let cos_a = v10.dot_product(v30);
        let cos_b = v12.dot_product(v32);

        if cos_a < 0 && cos_b < 0 {
            // A > 90 and B > 90
            // A + B > 180
            return false;
        }

        if cos_a >= 0 && cos_b >= 0 {
            // A <= 90 and B <= 90
            // A + B <= 180
            return true;
        }

        let sn_a = v10.cross_product(v30).unsigned_abs(); // A <= 180
        let sn_b = v12.cross_product(v32).unsigned_abs(); // B <= 180

        if cos_a < 0 {
            // cosA < 0
            // cosB >= 0
            let sin_a_cos_b = UInt128::multiply(sn_a, cos_b as u64); // positive
            let cos_a_sin_b = UInt128::multiply(cos_a.unsigned_abs(), sn_b); // negative

            sin_a_cos_b >= cos_a_sin_b
        } else {
            // cosA >= 0
            // cosB < 0
            let sin_a_cos_b = UInt128::multiply(sn_a, cos_b.unsigned_abs()); // negative
            let cos_a_sin_b = UInt128::multiply(cos_a as u64, sn_b); // positive

            cos_a_sin_b >= sin_a_cos_b
        }
    }
}

use crate::delaunay::vertex::DVertex;

#[derive(Debug, Clone, Copy)]
pub struct DTriangle {
    pub index: usize,
    pub vertices: [DVertex; 3],
    pub neighbors: [usize; 3],
}

impl DTriangle {
    pub fn neighbor_by_order(&self, order: usize) -> usize {
        unsafe {
            *self.neighbors.get_unchecked(order)
        }
    }

    pub fn vertex_by_order(&self, order: usize) -> DVertex {
        unsafe {
            *self.vertices.get_unchecked(order)
        }
    }

    pub fn va(&self) -> DVertex {
        self.vertices[0]
    }

    pub fn vb(&self) -> DVertex {
        self.vertices[1]
    }

    pub fn vc(&self) -> DVertex {
        self.vertices[2]
    }

    pub fn na(&self) -> usize {
        self.neighbors[0]
    }

    pub fn nb(&self) -> usize {
        self.neighbors[1]
    }

    pub fn nc(&self) -> usize {
        self.neighbors[2]
    }

    pub fn new() -> Self {
        Self {
            index: usize::MAX,
            vertices: [DVertex::empty(); 3],
            neighbors: [usize::MAX; 3],
        }
    }

    pub fn abc(index: usize, a: DVertex, b: DVertex, c: DVertex) -> Self {
        Self {
            index,
            vertices: [a, b, c],
            neighbors: [usize::MAX; 3],
        }
    }

    pub fn abc_bc_ac_ab(index: usize, a: DVertex, b: DVertex, c: DVertex, bc: usize, ac: usize, ab: usize) -> Self {
        Self {
            index,
            vertices: [a, b, c],
            neighbors: [bc, ac, ab],
        }
    }

    pub fn neighbor(&self, vertex: usize) -> usize {
        #[cfg(debug_assertions)]
        {
            for i in 0..3 {
                if self.vertices[i].index == vertex {
                    return self.neighbors[i];
                }
            }

            panic!("Neighbor vertex is not present");
        }

        #[cfg(not(debug_assertions))]
        {
            for i in 0..2 {
                if self.vertices[i].index == vertex {
                    return self.neighbors[i];
                }
            }
            self.neighbors[2]
        }
    }

    pub fn opposite(&self, neighbor: usize) -> usize {
        #[cfg(debug_assertions)]
        {
            for i in 0..3 {
                if self.neighbors[i] == neighbor {
                    return i;
                }
            }

            panic!("Neighbor is not present");
        }

        #[cfg(not(debug_assertions))]
        {
            for i in 0..2 {
                if self.neighbors[i] == neighbor {
                    return i;
                }
            }

            2
        }
    }

    pub fn update_opposite(&mut self, old_neighbor: usize, new_neighbor: usize) {
        let index = self.opposite(old_neighbor);
        unsafe {
            *self.neighbors.get_unchecked_mut(index) = new_neighbor;
        }
    }
}

impl Default for DTriangle {
    fn default() -> Self {
        Self::new()
    }
}

use crate::delaunay::triangle::DTriangle;
use crate::index::{Index, NIL_INDEX};

#[derive(Debug, Clone, Copy)]
pub(crate) struct MSlice {
    a: usize,
    b: usize
}

impl MSlice {
    pub fn new(a: usize, b: usize) -> Self {
        Self { a, b }
    }
}

#[derive(Debug, Clone, Copy)]
struct Edge {
    pub id: usize,
    pub edge: usize,
    pub triangle: usize
}

impl Edge {
    pub const EMPTY: Edge = Edge {
        id: 0,
        edge: 0,
        triangle: 0,
    };
}

pub(crate) struct MSliceBuffer {
    vertex_count: usize,
    edges: Vec<Edge>,
    vertex_marks: Vec<bool>,
}

impl MSliceBuffer {
    pub(crate) fn new(vertex_count: usize, slices: &[MSlice]) -> Self {
        let mut vertex_marks = vec![false; vertex_count];
        let mut edges = vec![Edge::EMPTY; slices.len()];

        for (i, slice) in slices.iter().enumerate() {
            unsafe {
                *vertex_marks.get_unchecked_mut(slice.a) = true;
                *vertex_marks.get_unchecked_mut(slice.b) = true;

                let id = Self::id(vertex_count, slice.a, slice.b);
                *edges.get_unchecked_mut(i) = Edge { id, edge: NIL_INDEX, triangle: NIL_INDEX };
            }
        }

        edges.sort_by(|a, b| a.id.cmp(&b.id));

        Self {
            vertex_count,
            edges,
            vertex_marks
        }
    }

    pub fn add_connections(&mut self, triangles: &mut [DTriangle]) {
        let n = triangles.len();

        for i in 0..n {
            let mut j0 = 1;
            let mut j1 = 2;

            // Using unsafe to bypass bounds checking for performance reasons.
            // We guarantee safety by ensuring that:
            // 1. The outer loop iterates only up to the length of the triangles Vec,
            //    making 'i' a valid index.
            // 2. The find() function and edge.triangle always produce valid indices.
            // 3. We are not resizing the triangles array.
            unsafe {
                let vertices = triangles.get_unchecked(i).vertices;
                for j2 in 0..3 {
                    let a = vertices[j1].index;
                    let b = vertices[j2].index;

                    if let Some(edge_index) = self.find(a, b) {
                        let mut edge = self.edges[edge_index];

                        if edge.triangle.is_nil() {
                            edge.triangle = i;
                            edge.edge = j0;
                            self.edges[edge_index] = edge;
                        } else {
                            let triangle = triangles.get_unchecked_mut(i);
                            triangle.neighbors[j0] = edge.triangle;

                            let neighbor = triangles.get_unchecked_mut(edge.triangle);
                            neighbor.neighbors[edge.edge] = i;
                        }
                    }
                    j0 = j1;
                    j1 = j2;
                }
            }
        }
    }

    fn find(&self, a: usize, b: usize) -> Option<usize> {
        if !(self.vertex_marks[a] && self.vertex_marks[b]) {
            return None;
        }

        let id = Self::id(self.vertex_count, a, b);

        if let Ok(pos) = self.edges.binary_search_by(|edge| edge.id.cmp(&id)) {
            return Some(pos);
        }

        None
    }

    fn id(n: usize, a: usize, b: usize) -> usize {
        if a < b {
            a * n + b
        } else {
            b * n + a
        }
    }

}

use i_overlay::i_float::bit_pack::{BitPack, BitPackVec};
use i_overlay::i_float::triangle::Triangle;
use i_overlay::i_shape::int::shape::IntShape;
use crate::delaunay::vertex::DVertex;
use crate::monotone::mnav_node::MNavNode;

#[derive(Clone, Debug, Copy, PartialEq)]
pub enum MNodeType {
    End,
    Start,
    Merge,
    Split,
}

impl MNodeType {
    fn to_usize(self) -> usize {
        match self {
            MNodeType::End => 0,
            MNodeType::Start => 1,
            MNodeType::Merge => 2,
            MNodeType::Split => 3
        }
    }
}

#[derive(Clone, Debug, Copy)]
pub struct MSpecialNode {
    pub index: usize,
    pub node_type: MNodeType,
    pub sort: BitPack,
}

impl MSpecialNode {
    pub(crate) fn node_type(&self) -> MNodeType {
        self.node_type
    }
}

pub struct NodeLayout {
    pub nav_nodes: Vec<MNavNode>,
    pub spec_nodes: Vec<MSpecialNode>,
}

pub trait ShapeNodeLayout {
    fn node_layout(&self) -> NodeLayout;
}

impl ShapeNodeLayout for IntShape {
    fn node_layout(&self) -> NodeLayout {
        let mut n = 0;
        for path in self.iter() {
            n += path.len();
        }

        let mut verts = vec!(MNavNode::EMPTY; n);
        let mut nodes = Vec::new();

        let mut s = 0;
        for path in self.iter() {
            let mut i0 = path.len() - 2;

            let mut p0 = path[i0];

            let mut i1 = i0 + 1;

            let mut p1 = path[i1];

            for (i2, &p2) in path.iter().enumerate() {
                let i = i1 + s;

                let b0 = p0.bit_pack();
                let b1 = p1.bit_pack();
                let b2 = p2.bit_pack();

                let c0 = b0 > b1 && b1 < b2;
                let c1 = b0 < b1 && b1 > b2;

                if c0 || c1 {
                    let is_cw = Triangle::is_clockwise_point(p0, p1, p2);
                    let node_type = if c0 {
                        if is_cw { MNodeType::Start } else { MNodeType::Split }
                    } else if is_cw { MNodeType::End } else {
                        MNodeType::Merge
                    };
                    nodes.push(MSpecialNode { index: i, node_type, sort: b1 })
                }

                unsafe {
                    *verts.get_unchecked_mut(i) = MNavNode {
                        next: i2 + s,
                        index: i,
                        prev: i0 + s,
                        vert: DVertex::new(i, p1),
                    };
                }

                i0 = i1;
                i1 = i2;

                p0 = p1;
                p1 = p2;
            }

            s += path.len();
        }

        nodes.sort_by(|a, b| {
            if a.sort != b.sort {
                a.sort.cmp(&b.sort)
            } else {
                a.node_type.to_usize().cmp(&b.node_type.to_usize())
            }
        });

        NodeLayout { nav_nodes: verts, spec_nodes: nodes }
    }
}

impl<T> Drop for IdMap<T> {
    #[inline]
    fn drop(&mut self) {
        unsafe { self.drop_values() }
    }
}

impl<T: Clone> Clone for IdMap<T> {
    #[inline]
    fn clone(&self) -> Self {
        let ids = self.ids.clone();
        let cap = self.values.capacity();
        let mut values = Vec::with_capacity(cap);
        unsafe {
            for id in &ids {
                ptr::write(values.get_unchecked_mut(id),
                           self.values.get_unchecked(id).clone());
            }
        }
        IdMap {
            ids,
            values,
            space: cap,
        }
    }

    #[inline]
    fn clone_from(&mut self, other: &Self) {
        unsafe { self.drop_values() };
        self.ids.clone_from(&other.ids);

        let cap = other.values.capacity();
        self.values.reserve(cap);
        unsafe {
            for id in &self.ids {
                ptr::write(self.values.get_unchecked_mut(id),
                           other.values.get_unchecked(id).clone());
            }
        }
    }
}

// This receiver was previously polled. But now we are dropped instead. The sender
// has never observed our RECEIVING state and we are resposnible for dropping the
// waker we previously wrote. The sender becomes responsible for deallocating the
// channel.
#[cfg(feature = "async")]
RECEIVING => {
    // SAFETY: The RECEIVING state guarantees we have written a waker.
    unsafe { channel.drop_waker() };
}

/// # Safety
/// Check if a byte slice is valid.
#[target_feature(enable = "sse4.1")]
#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub unsafe fn hex_check_sse(src: &[u8]) -> bool {
    hex_check_sse_with_case(src, CheckCase::None)
}

#[derive(Eq, PartialEq)]
/// # Safety
/// Check if a byte slice is valid on given check_case.
#[target_feature(enable = "sse4.1")]
#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub unsafe fn hex_check_sse_with_case(mut src: &[u8], check_case: CheckCase) -> bool {
    let ascii_zero = _mm_set1_epi8((b'0' - 1) as i8);
    let ascii_nine = _mm_set1_epi8((b'9' + 1) as i8);
    let ascii_ua = _mm_set1_epi8((b'A' - 1) as i8);
    let ascii_uf = _mm_set1_epi8((b'F' + 1) as i8);
    let ascii_la = _mm_set1_epi8((b'a' - 1) as i8);
    let ascii_lf = _mm_set1_epi8((b'f' + 1) as i8);

    while src.len() >= 16 {
        let unchecked = _mm_loadu_si128(src.as_ptr() as *const _);

        let gt0 = _mm_cmpgt_epi8(unchecked, ascii_zero);
        let lt9 = _mm_cmplt_epi8(unchecked, ascii_nine);
        let valid_digit = _mm_and_si128(gt0, lt9);

        let (valid_la_lf, valid_ua_uf) = match check_case {
            CheckCase::None => {
                let gtua = _mm_cmpgt_epi8(unchecked, ascii_ua);
                let ltuf = _mm_cmplt_epi8(unchecked, ascii_uf);

                let gtla = _mm_cmpgt_epi8(unchecked, ascii_la);
                let ltlf = _mm_cmplt_epi8(unchecked, ascii_lf);

                (
                    Some(_mm_and_si128(gtla, ltlf)),
                    Some(_mm_and_si128(gtua, ltuf)),
                )
            }
            CheckCase::Lower => {
                let gtla = _mm_cmpgt_epi8(unchecked, ascii_la);
                let ltlf = _mm_cmplt_epi8(unchecked, ascii_lf);

                (Some(_mm_and_si128(gtla, ltlf)), None)
            }
            CheckCase::Upper => {
                let gtua = _mm_cmpgt_epi8(unchecked, ascii_ua);
                let ltuf = _mm_cmplt_epi8(unchecked, ascii_uf);
                (None, Some(_mm_and_si128(gtua, ltuf)))
            }
        };

        let valid_letter = match (valid_la_lf, valid_ua_uf) {
            (Some(valid_lower), Some(valid_upper)) => _mm_or_si128(valid_lower, valid_upper),
            (Some(valid_lower), None) => valid_lower,
            (None, Some(valid_upper)) => valid_upper,
            _ => unreachable!(),
        };

        let ret = _mm_movemask_epi8(_mm_or_si128(valid_digit, valid_letter));

        if ret != T_MASK {
            return false;
        }

        src = &src[16..];
    }
    hex_check_fallback_with_case(src, check_case)
}

#[target_feature(enable = "neon")]
#[cfg(target_arch = "aarch64")]
pub unsafe fn hex_check_neon(src: &[u8]) -> bool {
    hex_check_neon_with_case(src, CheckCase::None)
#[target_feature(enable = "neon")]
#[cfg(target_arch = "aarch64")]
pub unsafe fn hex_check_neon_with_case(mut src: &[u8], check_case: CheckCase) -> bool {
    let ascii_zero = vdupq_n_u8(b'0' - 1);
    let ascii_nine = vdupq_n_u8(b'9' + 1);
    let ascii_ua = vdupq_n_u8(b'A' - 1);
    let ascii_uf = vdupq_n_u8(b'F' + 1);
    let ascii_la = vdupq_n_u8(b'a' - 1);
    let ascii_lf = vdupq_n_u8(b'f' + 1);

    while src.len() >= 16 {
        let unchecked = vld1q_u8(src.as_ptr() as *const _);

