    type Ok = Json;
    type Error = Error;

    fn serialize_key<T: ser::Serialize + ?Sized>(&mut self, key: &T) -> Result<(), Error> {
        if let Json(JsonInner::String(s)) = Json::from_serialize(key)? {
            self.next_key = Some(s);
            Ok(())
        } else {
            use serde::de::Error;
            Err(Error::custom("can only serialize maps with stringy keys"))
