fn slice_move_source_array_panic_unwind_test() {
    let drop_count = Cell::new(0);
    let data = [
        DropCounter::new(&drop_count),
        DropCounter::new(&drop_count),
        DropCounter::new(&drop_count),
    ];

    let mut move_count = 0;
    panic::catch_unwind(AssertUnwindSafe(|| {
        data.move_elements(|x| {
            move_count += 1;
            if move_count == 2 {
                panic!();
            }

            drop(x);
        });
    }))
    .unwrap_or(());

