	match File::open("/dev/urandom") {
		Ok(fd) => {
			let mut entropy: Vec<u8> = vec![42; amt];
			let mut reader = BufReader::new(fd);
			match reader.read_exact(&mut entropy[..amt]) {
				Ok(_) => entropy,
				Err(_) => backup_entropy(amt),
			}
		}
		Err(_) => {
			// Ugh, let's try for /dev/random
